```yaml
name: Auto‑approve workflows for first‑time contributors

on:
  pull_request_target:
    types: [labeled, synchronize]
    branches:
      - main
      - release-**

permissions:
  contents: read

jobs:
  approve:
    runs-on: ubuntu-latest
    if: github.event.pull_request.head.repo.full_name == github.repository
    permissions:
      actions: write
    steps:
      - name: Determine if approval is needed
        id: check
        uses: actions/github-script@v6
        with:
          script: |
            const pr = context.payload.pull_request;
            const owner = context.repo.owner;
            const repo = context.repo.repo;
            const author = pr.user.login;
            const okToTestLabel = 'ok-to-test';

            // Check if the PR has the ok-to-test label
            const hasOkToTest = pr.labels.some(l => l.name === okToTestLabel);

            // Count all PRs by this author (including the current one)
            let page = 1;
            let authorPrCount = 0;
            while (true) {
              const { data: prs } = await github.rest.pulls.list({
                owner,
                repo,
                state: 'all',
                per_page: 100,
                page
              });
              if (prs.length === 0) break;
              authorPrCount += prs.filter(p => p.user.login === author).length;
              if (prs.length < 100) break;
              page++;
            }

            const isReturning = authorPrCount > 1;
            const approve = isReturning || hasOkToTest;
            core.info(`Author: ${author}`);
            core.info(`Returning contributor: ${isReturning}`);
            core.info(`Has ${okToTestLabel} label: ${hasOkToTest}`);
            core.info(`Approval needed: ${approve}`);
            core.setOutput('approve', approve ? 'true' : 'false');

      - name: Approve pending workflow run
        if: steps.check.outputs.approve == 'true'
        uses: actions/github-script@v6
        with:
          script: |
            const pr = context.payload.pull_request;
            const owner = context.repo.owner;
            const repo = context.repo.repo;
            const currentRunId = context.runId;

            // Find the pending workflow run for this PR (excluding the current run)
            const { data: runs } = await github.rest.actions.listWorkflowRunsForRepo({
              owner,
              repo,
              status: 'pending',
              event: 'pull_request_target',
              per_page: 100
            });

            const pendingRun = runs.workflow_runs.find(r =>
              r.id !== currentRunId &&
              r.head_branch === pr.head.ref
            );

            if (!pendingRun) {
              core.info('No pending workflow run found to approve.');
              return;
            }

            await github.rest.actions.approveWorkflowRun({
              owner,
              repo,
              run_id: pendingRun.id
            });

            core.info(`Approved workflow run ${pendingRun.id}`);
```

